import{_ as t,o as a,c as n,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — Delete Workspace (FR 3.4.15)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-15-delete-workspace/plan.md","filePath":"feature/agency-workspace/3-4-15-delete-workspace/plan.md"}'),o={name:"feature/agency-workspace/3-4-15-delete-workspace/plan.md"};function i(d,e,r,h,s,l){return a(),n("div",null,[...e[0]||(e[0]=[c(`<h1 id="plan-—-delete-workspace-fr-3-4-15" tabindex="-1">Plan — Delete Workspace (FR 3.4.15) <a class="header-anchor" href="#plan-—-delete-workspace-fr-3-4-15" aria-label="Permalink to &quot;Plan — Delete Workspace (FR 3.4.15)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — Trạng thái tài liệu: <strong>Implemented</strong>. Plan này giữ nguyên nội dung phân tích kỹ thuật cũ (viết khi còn ở trạng thái Proposed); các mục dưới không rewrite lại toàn bộ, chỉ các dòng &quot;chưa tồn tại/dự kiến&quot; đã lỗi thời so với code thật — xem spec.md để biết method/route thật đã implement.</p><h2 id="_1-pham-vi-ky-thuat-du-kien" tabindex="-1">1. Phạm vi kỹ thuật (dự kiến) <a class="header-anchor" href="#_1-pham-vi-ky-thuat-du-kien" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật (dự kiến)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File đã implement</td><td><code>WorkspaceServiceImpl.deleteWorkspace()</code>, <code>WorkspaceServiceImpl.restoreWorkspace()</code> (đã tồn tại, đã code)</td></tr><tr><td>File đã có, đã dùng</td><td><code>Workspace</code> entity (<code>status</code> kiểu <code>EntityStatus</code>, <code>deletedAt</code> — đã được <code>deleteWorkspace</code>/<code>restoreWorkspace</code> ghi thật), <code>WorkspaceController</code></td></tr></tbody></table><h2 id="_2-api-contract-đe-xuat-chua-code" tabindex="-1">2. API Contract (đề xuất, chưa code) <a class="header-anchor" href="#_2-api-contract-đe-xuat-chua-code" aria-label="Permalink to &quot;2. API Contract (đề xuất, chưa code)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /api/v1/workspaces/{id}</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: null }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/workspaces/{id}/restore</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { ...restored workspace... } }</span></span></code></pre></div><p>Cần xác nhận path param thật khớp <code>{workspaceId}</code> như các endpoint khác (pattern hiện tại của <code>WorkspaceController</code>).</p><h2 id="_3-data-model-du-kien" tabindex="-1">3. Data Model (dự kiến) <a class="header-anchor" href="#_3-data-model-du-kien" aria-label="Permalink to &quot;3. Data Model (dự kiến)&quot;">​</a></h2><ul><li><code>Workspace.status = SOFT_DELETED</code>, <code>deletedAt = now()</code> — field đã tồn tại sẵn trên entity, chưa từng được ghi bởi service nào (xác nhận cần review <code>Workspace</code> entity trước khi code).</li><li>Cần xác nhận cơ chế &quot;toàn bộ dữ liệu trong Workspace (Task, Campaign, Material...) chuyển <code>inactive</code>&quot; — đây là cascade sang domain khác (Task/Campaign), <strong>chưa rõ có sẵn cột trạng thái tương ứng hay không</strong>, cần thiết kế kỹ thuật riêng, có thể cần transaction lớn hoặc batch job.</li><li>Không migration schema (field đã có sẵn), nhưng cần xác nhận cascade update có cần migration ở domain Task/Campaign hay không.</li></ul><h2 id="_4-luong-xu-ly-du-kien" tabindex="-1">4. Luồng xử lý (dự kiến) <a class="header-anchor" href="#_4-luong-xu-ly-du-kien" aria-label="Permalink to &quot;4. Luồng xử lý (dự kiến)&quot;">​</a></h2><ol><li>Check role: chỉ Agency OWNER (không phải Workspace MANAGER) — theo spec.md mục 3 &quot;chỉ OWNER&quot; — cần xác nhận cách resolve OWNER ở cấp Workspace (không có <code>AgencyMember</code> trực tiếp trong path <code>/workspaces/{id}</code>, cần lấy <code>agencyId</code> từ Workspace rồi so <code>agency.ownerId</code>).</li><li>Confirm dialog ở FE (nhập tên Workspace xác nhận) — không phải trách nhiệm BE.</li><li><code>findWorkspaceOrThrow(id)</code> → 404.</li><li>Check owner → 403 <code>FORBIDDEN</code> nếu không phải Owner (kể cả Manager của Workspace đó).</li><li>Set <code>status = SOFT_DELETED</code>, <code>deletedAt = now()</code>.</li><li>Cascade set toàn bộ Task/Campaign/Material liên quan sang <code>inactive</code> — cần thiết kế riêng.</li><li>Restore: check trong 30 ngày kể từ <code>deletedAt</code>, nếu quá hạn → 410 <code>RESTORE_WINDOW_EXPIRED</code>; nếu hợp lệ, khôi phục đúng trạng thái dữ liệu trước đó (không reset).</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td>Cần xác nhận domain Task/Campaign đã có cột trạng thái tương thích cascade &quot;inactive&quot; chưa</td></tr><tr><td>Bị chặn</td><td>Không</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Chưa có endpoint, chưa có service</strong> — rủi ro lớn nhất, cần thiết kế kỹ thuật riêng trước khi ước lượng effort.</li><li><strong>Cascade &quot;toàn bộ dữ liệu chuyển inactive&quot;</strong> là thay đổi xuyên domain (Task, Campaign, Material), không chỉ nằm trong Workspace domain — cần phối hợp với owner của các domain đó.</li><li><strong>Restore đúng trạng thái trước đó (không reset về backlog)</strong> — đòi hỏi lưu snapshot trạng thái tại thời điểm xóa, không đơn giản chỉ lật cờ <code>inactive</code> → <code>active</code>.</li><li><strong>Vai trò &quot;Owner cấp Workspace&quot; chưa tồn tại trong code thật</strong> (Owner chỉ tồn tại ở cấp Agency theo mọi FR khác đã code — 3.4.16/18/19/20/21 đều dùng MANAGER, không có OWNER) — spec.md tự ghi &quot;đề xuất — chưa xác nhận&quot; cho Role; đây là điểm mâu thuẫn tiềm tàng cần BA làm rõ trước khi code (có thể ý là Agency OWNER của Agency chứa Workspace đó, không phải role riêng ở cấp Workspace).</li></ul>`,15)])])}const k=t(o,[["render",i]]);export{u as __pageData,k as default};
